package com.scalar.db.nativejdbc.samples.springdata;

import org.jspecify.annotations.Nullable;
import org.springframework.data.annotation.Id;
import org.springframework.data.annotation.Version;
import org.springframework.data.relational.core.mapping.Table;

/**
 * An item, its key generated by the database, its version checked on every update. The table's name
 * is derived, so that the dialect spells it as the database stores it: upper case on Oracle.
 */
@Table
public class Item {
  @Id private @Nullable Long id;
  private String name;
  private int qty;
  @Version private @Nullable Integer version;

  public Item(String name, int qty) {
    this.name = name;
    this.qty = qty;
  }

  public @Nullable Long getId() {
    return id;
  }

  public void setId(@Nullable Long id) {
    this.id = id;
  }

  public String getName() {
    return name;
  }

  public void setName(String name) {
    this.name = name;
  }

  public int getQty() {
    return qty;
  }

  public void setQty(int qty) {
    this.qty = qty;
  }

  public @Nullable Integer getVersion() {
    return version;
  }

  public void setVersion(@Nullable Integer version) {
    this.version = version;
  }
}
